/**
 * Plan 2 — what the 28-day run NEVER touched.
 *
 * plan.ts (295 steps) followed money, safeguarding and the tenant boundary
 * through the screens a provider uses every day, and by 13 Sept almost all of
 * it passes. This plan is built from the other direction: an inventory of the
 * whole product surface (80 API route files, ~180 registered views across six
 * portals, seven public routes, 15 background sweeps) minus what plan.ts
 * already exercises. The gap report that produced it is in the test-gaps
 * scratchpad note; the short version:
 *
 *   · Whole APIs with zero steps: payroll runs, appraisals, leave config and
 *     entitlement, availability requests, location-staff, expense claims,
 *     suppliers/purchasing, income/expense series, block bundles, timetables,
 *     calendar events, meal shop orders, inventory ordering, messages
 *     folders/templates/broadcast, email scheduling/suppression/inbound,
 *     notification prefs, SSE events, AI compose, platform leads/support/at-risk
 *     /engagement/features/pricing, HO overview + oversight + feature control,
 *     franchise territories, posts reactions/RSVP, feedback, privacy export,
 *     wallet summary, learning notify, credentials types, onboarding files,
 *     reference files.
 *   · Cross-cutting: the role matrix was tested on ONE area; franchise
 *     isolation on ~10 of ~45 list endpoints; i18n only in the parent portal;
 *     mobile only for registers/parent; double-submit on three routes; no
 *     input-limit, CSV-formula, upload-type, time-zone-on-sweeps, pagination,
 *     back-button or "did the notification really fire" sweeps.
 *
 * Same shape as plan.ts so the Testing page can load it unchanged. Each step
 * additionally says HOW it is run (method) and what it needs (prereq):
 *
 *   api      — a request with a token; runnable headless from a terminal or
 *              a scratchpad .test.mts against the dev/staging API
 *   code     — settled by reading the named file; no environment needed
 *   browser  — needs a real browser or phone; says which
 *
 * Tokens used below (see PREREQS2): $A freelancer owner · $B unrelated
 * provider · $C head-office owner (company with franchises) · $F1/$F2 its two
 * franchises · $S plain staff of $A · $L a site-lead staff of $C assigned to
 * venue V1 · $P parent of $A · $P2 parent of $B · $H the HQ platform account.
 * API = the staging API origin (or http://localhost:4000).
 *
 * Day 1 = Fri 9 Oct 2026, the day after plan.ts ends. Money, safeguarding and
 * permissions come first; comfort (i18n, mobile, tours) comes last.
 */

import type { Day, Step } from "./plan";

export type Method = "api" | "code" | "browser";

export interface Step2 extends Step {
  /** Short name, for the list and the export. */
  title: string;
  /** How the step is run — headless where at all possible. */
  method: Method;
  /** What must exist before this step can be attempted. */
  prereq?: string;
}

export interface Day2 extends Day {
  steps: Step2[];
}

export const PLAN2_START = "2026-10-09";

